import{_ as o}from"./chunks/neiruha.D3XV6UDq.js";import{_ as a,c as r,a0 as e,o as s}from"./chunks/framework.p2VkXzrt.js";const i="/assets/05-promt-01.C-DfkHpm.jpg",l="/assets/05-promt-02.BvANk65W.jpg",n="/assets/promt-tip.B41fG5f4.png",_=JSON.parse('{"title":"Открытие №5. Промт-инжиниринг","description":"","frontmatter":{},"headers":[],"relativePath":"slides/05-prompt-engineering.md","filePath":"slides/05-prompt-engineering.md"}'),p={name:"slides/05-prompt-engineering.md"};function u(c,t,h,q,d,m){return s(),r("div",null,t[0]||(t[0]=[e('<h1 id="открытие-no5-промт-инжиниринг" tabindex="-1">Открытие №5. Промт-инжиниринг <a class="header-anchor" href="#открытие-no5-промт-инжиниринг" aria-label="Permalink to &quot;Открытие №5. Промт-инжиниринг&quot;">​</a></h1><p><strong>Вопрос:</strong><br> Как заставить ИИ работать так, чтобы это было гениально?</p><hr><h2 id="цитата-для-вдохновения" tabindex="-1">Цитата для вдохновения <a class="header-anchor" href="#цитата-для-вдохновения" aria-label="Permalink to &quot;Цитата для вдохновения&quot;">​</a></h2><blockquote><p>&quot;Промт — мать порока. Запретный промт - сладок&quot;<br> — Нейруха</p></blockquote><hr><h2 id="техники" tabindex="-1">Техники <a class="header-anchor" href="#техники" aria-label="Permalink to &quot;Техники&quot;">​</a></h2><ul><li><p><strong>Погружение:</strong><br> Перед началом работы попросите ИИ описать, как он будет выполнять задачу, и погрузите его в нужное настроение.</p></li><li><p><strong>Мнемотехники:</strong><br> Используйте смешные образы и ассоциации, чтобы запоминать сложные вещи. Я выучил два номера карт, благодаря тому, что ИИ создавал уникальные образы.</p></li><li><p><strong>Комментарии в тексте:</strong><br> Добавляйте подсказки прямо в документ:</p><ul><li>&quot;Нейруха, здесь нужно расширить идею.&quot;</li><li>&quot;Добавь сюда лёгкий юмор.&quot;</li></ul></li><li><p><strong>Игра &quot;Тепло-холодно&quot;:</strong><br> Позвольте ИИ угадывать ваши мысли, давая подсказки, насколько он близок к правильному ответу.</p></li><li><p><strong>Циклическая обратная связь:</strong><br> Генерируйте текст, улучшайте его, изменяя вводные данные. Этот метод работает и для изображений: создаёшь картинку, используешь её как референс, добавляешь детали и повторяешь.</p></li></ul><hr><div class="image-row"><img src="'+i+'" alt="Промт-инжиниринг в действии" class="thumb"><img src="'+l+'" alt="Циклическая обратная связь" class="thumb"></div><hr><h2 id="инсаит" tabindex="-1">Инсайт <a class="header-anchor" href="#инсаит" aria-label="Permalink to &quot;Инсайт&quot;">​</a></h2><blockquote> &quot;Когда я отказался от слова &quot;промпт&quot; передо мной открылся целый мир - вопросов, подсказок, &quot;магнитов&quot;, &quot;импульсов&quot;, &quot;генераторов&quot;, &quot;лассо&quot; и всего, что можно вообразить в отношении текста. Ранее текст - был джунглями для меня, увлекательно, но сложно и можно заблудиться. Теперь я хожу &quot;в текст&quot; и чувствую себя в этом лесу свободным, диким и могучим. Я понял - ключ к &quot;21 веку&quot; в том, чтобы хорошо владеть языком. И именно в этом будущее. ИИ понимает нас ровно настолько, насколько мы умеем хорошо выражать свои желания и задавать те вопросы, которые нужны.&quot; </blockquote><hr><h2 id="практическии-вывод" tabindex="-1">Практический вывод <a class="header-anchor" href="#практическии-вывод" aria-label="Permalink to &quot;Практический вывод&quot;">​</a></h2><div class="practical-tip"><img src="'+n+'" alt="Иконка магического ключа" class="tip-icon"><p> Не бойся экспериментировать с промтами. Чем точнее и творчески ты подойдёшь к задаче, тем удивительнее будет результат. <strong>Промт — это искусство, которое делает ИИ твоим партнёром.</strong></p></div><hr><h2 id="ключевая-идея" tabindex="-1">Ключевая идея <a class="header-anchor" href="#ключевая-идея" aria-label="Permalink to &quot;Ключевая идея&quot;">​</a></h2><p>Промт — это не просто текст, это мост между человеком и ИИ. Чем больше ты изучаешь и пробуешь, тем быстрее и лучше достигаешь результата.</p><hr><div class="neiruha-comment"><img src="'+o+'" alt="Нейруха" class="neiruha-avatar"><p> *(с хитрым прищуром)* Ты ведь знаешь, что хороший промт может заменить целую команду программистов? Но не забывай: магия начинается с твоего воображения. </p></div>',21)]))}const f=a(p,[["render",u]]);export{_ as __pageData,f as default};
